	n := 17 + 4*v
	pair := 0
	for r := n - 1; r >= 1; r -= 2 {
		if r == 6 {
			r--
		}
		for step := 0; step < n; step++ {
			y := step
			if pair%2 == 0 {
				y = n - 1 - step
			}
			for x := r; x >= r-1; x-- {
				if m.areas[y][x] == 0 {
					m.order = append(m.order,
						Point{x, y})
				}
			}
		}
		pair++
	}
	return m
